def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def simulated_annealing(lb, ub, initial_temperature, cooling_rate, num_steps):
        current_solution = rng.uniform(lb, ub, size=dim)
        current_fitness = func(current_solution)
        temperature = initial_temperature

        for _ in range(num_steps):
            new_solution = clip(rng.normal(loc=current_solution, scale=np.sqrt(ub-lb), size=dim))
            new_fitness = func(new_solution)

            if new_fitness < current_fitness:
                current_solution = new_solution
                current_fitness = new_fitness
            else:
                delta = new_fitness - current_fitness
                probability = np.exp(-delta / temperature)
                if rng.uniform(0, 1) < probability:
                    current_solution = new_solution
                    current_fitness = new_fitness

            temperature *= cooling_rate

        return current_solution

    best_solution = None
    best_fitness = float('inf')

    for _ in range(budget):
        solution = simulated_annealing(lb, ub, rng.uniform(1, 100), 0.99, num_steps=100)
        fitness = func(solution)

        if fitness < best_fitness:
            best_solution = solution
            best_fitness = fitness

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate_candidate(mean, sigma):
        candidate = mean + sigma * (rng.standard_normal(dim) - 0.5)
        return clip(candidate)

    n_candidates = int(np.sqrt(budget))
    population_size = n_candidates * 10

    candidates = [generate_candidate(np.zeros(dim), 1) for _ in range(population_size)]
    scores = [func(candidates[i]) for i in range(population_size)]

    for _ in range(int(budget / (population_size + 1))):
        if len(scores) > population_size:
            min_idx = np.argmin(scores)
            best_candidate = candidates[min_idx]
            for j in range(n_candidates):
                candidate_idx = rng.choice(len(candidates), replace=False)
                new_score = func(candidates[candidate_idx])
                old_score = scores[candidate_idx]
                if new_score < old_score:
                    scores[candidate_idx] = new_score
                    candidates[candidate_idx] = generate_candidate(best_candidate, 1)
        else:
            for i in range(n_candidates):
                candidate_idx = rng.choice(len(candidates), replace=False)
                new_candidate = generate_candidate(candidates[candidate_idx], 1.5)
                scores.append(func(new_candidate))
                candidates.append(new_candidate)

    min_idx = np.argmin(scores)
    best_candidate = candidates[min_idx]
    return best_candidate
